from __future__ import absolute_import

from functools import partial

import time
from selenium.webdriver.common.by import By

from .common_page import CommonPage
from .panels.details import DetailPanel
from .panels.navigation import NavigationPanel
from .panels.view import ViewPanel


class Alarms(CommonPage):
    """
    The class corresponding to Alarms page on selenium_coam_cu web, all operations under Alarms page will be implemented
    or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver, version):
        if not self._instance_dict:
            self._instance_dict = {"Active Alarms": ActiveAlarmsPage(driver, version),
                                   "Alarm History": AlarmHistoryPage(driver, version),
                                   "Fault Toggling History": FaultTogglingHistoryPage(driver, version)
                                   }
        super(Alarms, self).__init__(driver, version, self._instance_dict)


class AlarmsCommonAction(NavigationPanel, ViewPanel, DetailPanel):

    def _input_filter_context(self, alarm_type, alarm_filter, alarm_filter_xpath, timeout):
        """
        This key word is for filtering the alarms using alarm filter
        :param alarm_type: str, it denotes page is active or historical
        :param alarm_filter: str, string to be written in alarm filter
        :param alarm_filter_xpath: str, xpath of alarm filter
        :param timeout: int, timeout
        """
        locator = (By.XPATH, alarm_filter_xpath)
        if alarm_filter:
            self._clear_filter(alarm_type)
            self.insert_text_to_enable_element(locator, alarm_filter, timeout)
        else:
            self._clear_filter(alarm_type)

    def _clear_filter(self, alarm_type):
        if self.element_exists((By.XPATH, self.locator.ALARM_FILTER_CLEAR_XPATH.format(alarm_type)), timeout=10):
            self.click_enabled_element((By.XPATH, self.locator.ALARM_FILTER_CLEAR_XPATH.format(alarm_type)))

    def _click_severity_type(self, severity_type, timeout):
        """
                This key word is for filtering the alarms using severity
                :param severity_type: str, [Critical, Minor, Major, Warning]
                :param timeout: int, timeout
                """
        severity_list = ['critical', 'major', 'minor', 'warning']
        for severity in severity_list:
            if 'checked' in self.get_attribute_by_xpath(self.locator.ALARM_MENU_SEVERITY_XPATH.format(severity),
                                                        attr_name='class'):
                self.click_enabled_element(self.locator.ALARM_MENU_SEVERITY_XPATH.format(severity), timeout)
        self.click_enabled_element(self.locator.ALARM_MENU_SEVERITY_XPATH.format(severity_type.lower()), timeout)

    def get_alarm_info_based_on_severity(self, alarm_type, severity_type, timeout):
        """
                This keyword will the all cell data of the alarm table and arranged in list of dict
                :param alarm_type: str, it denotes page is active or historical
                :param severity_type: str, [Critical, Minor, Major, Warning]
                :param timeout: int, timeout

                :return: list of dict, every dict info is one line of alarm tables
                """
        self._click_severity_type(severity_type, timeout)
        if self._is_alarm_table_empty(alarm_type):
            return "No Alarm found"
        else:
            return self._get_alarms_info(alarm_type, timeout)

    def _get_alarms_info(self, alarm_type, timeout):
        """
        This keyword is for getting all the details from alarm table

        :param alarm_type: str, it denotes page is active or historical
        :param timeout: int, timeout

        :return: list of dict, every dict info is one line of alarm tables
        """
        alarm_list = []
        key_list = self.get_fields_info_from_row(self.locator.ALARM_COLUMN_HEADER_XPATH.format(alarm_type), timeout)
        number_of_alarm_pages = self.get_text_by_xpath(self.locator.PAGINATION_PAGE_NUMBER.format(alarm_type),
                                                       timeout).split(" ")[-1]
        for page in range(1, int(number_of_alarm_pages) + 1):
            number_of_rows = len(self._driver.find_elements_by_xpath(self.locator.ALARMS_ROW_XPATH.format(alarm_type)))
            for row in range(1, number_of_rows + 1):
                severity = self._driver.execute_script(self.locator.SEVERITY_DATA_JQUERY.format(row - 1))
                value_list = self._get_alarm_row_data(row, key_list)
                value_list.insert(0, severity)
                alarm_list.append(dict(zip(key_list, value_list)))
            if page == int(number_of_alarm_pages):
                break
            else:
                self.click_enabled_element((By.CSS_SELECTOR, self.locator.PAGE_RIGHT_NAVIGATOR_CSS_PATH), timeout)
                time.sleep(5)
        return alarm_list

    def _get_alarm_row_data(self, row, column_length):
        """
        This key word will return all the column  data of given alarm table in a list

        :param row: int, row number
        :param column_length: int , number of columns

        :return: list of column data in row
        """
        alarm_row_details = []
        for cell in range(1, len(column_length)):
            alarm_row_details.append(self._driver.execute_script(self.locator.COLUMN_DATA_JQUERY.format(row, cell)))
        return alarm_row_details

    def get_alarms_info(self, alarm_type, alarm_filter=None, timeout=60):
        """
        This keyword will the all cell data of the alarm table and arranged in list of dict
        :param alarm_type: str, it denotes page is active or historical
        :param alarm_filter: str, alarm filter
        :param timeout: int, timeout

        :return: list of dict, every dict info is one line of alarm tables
        """
        self._input_filter_context(alarm_type, alarm_filter, self.locator.ACTIVE_ALARM_FILTER_XPATH.format(alarm_type),
                                   timeout
                                   )
        if self._is_alarm_table_empty(alarm_type):
            return "No Alarm found"
        else:
            return self._get_alarms_info(alarm_type, timeout)

    def _is_alarm_table_empty(self, alarm_type):
        """
        Return a boolean alarm table is empty or not

        :param alarm_type: str, type whether it is Active or Historical alarm
        :return: Bool, True or False
        """
        time.sleep(3)
        if self.element_exists((By.XPATH, self.locator.ALARM_EMPTY_XPATH.format(alarm_type))):
            return True
        return False

    def save_alarms(self, alarm_type, alarm_filter, timeout=60):
        """
        This keyword perform the download of active and historical alarms and return the status

        :param alarm_type: str, it denotes page is active or historical
        :param alarm_filter:
        :param timeout: int, timeout

        :return: Status of the download
        """
        self._input_filter_context(alarm_type, alarm_filter, self.locator.ACTIVE_ALARM_FILTER_XPATH.format(alarm_type),
                                   timeout)
        if self._is_alarm_table_empty(alarm_type):
            return "No Alarm found"
        else:
            self.click_enabled_element((By.XPATH, self.locator.SAVE_ALARMS_XPATH.format(alarm_type)))
            return "Saved Alarm successfully"


class ActiveAlarmsPage(object):
    MENU_ROUTE_LIST = ['bell', 'Active Alarms']

    def __init__(self, driver, version):
        self._view_panel = ActiveAlarmsPageViewPanel(driver, version)
        self.common_actions = {
            "get_active_alarm_info": self._view_panel.get_active_alarm_info,
            "save_current_alarms": self._view_panel.save_current_alarms,
            "get_active_alarm_info_based_on_severity": self._view_panel.get_active_alarm_info_based_on_severity
        }
        self.__dict__.update(self.common_actions)


class ActiveAlarmsPageViewPanel(ViewPanel):

    def __init__(self, driver, version):
        super(ActiveAlarmsPageViewPanel, self).__init__(driver, version)
        self.common_actions = {
            "get_active_alarm_info": partial(AlarmsCommonAction(driver, version).get_alarms_info,
                                             self.locator.ACTIVE_ALARM_TYPE_XPATH),
            "save_current_alarms": partial(AlarmsCommonAction(driver, version).save_alarms,
                                           self.locator.ACTIVE_ALARM_TYPE_XPATH),
            "get_active_alarm_info_based_on_severity":
                partial(AlarmsCommonAction(driver, version).get_alarm_info_based_on_severity,
                        self.locator.ACTIVE_ALARM_TYPE_XPATH)
        }
        self.__dict__.update(self.common_actions)


