class FaultTogglingHistoryPage(object):
    MENU_ROUTE_LIST = ['bell', 'Fault Toggling History']

    def __init__(self, driver, version):
        self._view_panel = FaultTogglingHistoryPageViewPanel(driver, version)

    def get_fault_toggling_history(self, alarm_state, fault_id, fault_name, fault_source, node_id, timeout):
        """
        Keyword for getting fault toggle alarm information shown in Active Alarms page

        :param alarm_state: str, State of the alarm
        :param fault_id: str, id of the  fault toggle alarm
        :param fault_name: str, Name of the fault toggle alarm
        :param fault_source: str, Source of the fault toggle alarm
        :param node_id: str, node id in which fault toggle alarm is present
        :param timeout: int, time to wait get alarm info, default is 60 second

        :return: list of dict, every dict info is one line of fault toggle alarm tables
        """
        return self._view_panel.get_fault_toggling_history(alarm_state, fault_id, fault_name, fault_source, node_id,
                                                           timeout)

    def save_fault_toggling_history(self, alarm_state, fault_id, fault_name, fault_source, node_id, timeout):
        """
        Keyword for saving fault toggle alarm file

        :param alarm_state: str, State of the alarm
        :param fault_id: str, id of the  fault toggle alarm
        :param fault_name: str, Name of the fault toggle alarm
        :param fault_source: str, Source of the fault toggle alarm
        :param node_id: str, node id in which fault toggle alarm is present
        :param timeout: int, time to wait get alarm info, default is 60 second

        :return: str, path of fault toggle alarm file or string says "No Alarm found" if alarms are present
        """
        return self._view_panel.save_fault_toggling_history(alarm_state, fault_id, fault_name, fault_source, node_id,
                                                            timeout)


class FaultTogglingHistoryPageViewPanel(ViewPanel):
    def __init__(self, driver, version):
        super(FaultTogglingHistoryPageViewPanel, self).__init__(driver, version)

    def get_fault_toggling_history(self, alarm_state, fault_id, fault_name, fault_source, node_id, timeout):
        """
        Keyword for getting fault toggle alarm information shown in Active Alarms page

        :param alarm_state: str, State of the alarm
        :param fault_id: str, id of the  fault toggle alarm
        :param fault_name: str, Name of the fault toggle alarm
        :param fault_source: str, Source of the fault toggle alarm
        :param node_id: str, node id in which fault toggle alarm is present
        :param timeout: int, time to wait get alarm info, default is 60 second

        :return: list of dict, every dict info is one line of fault toggle alarm tables
        """
        self.filter_fault_toggling(alarm_state, fault_id, fault_name, fault_source, node_id, timeout)
        return self._get_fault_toggling_alarm_info(timeout)

    def save_fault_toggling_history(self, alarm_state, fault_id, fault_name, fault_source, node_id, timeout):
        """
        Keyword for saving fault toggle alarm file

        :param alarm_state: str, State of the alarm
        :param fault_id: str, id of the  fault toggle alarm
        :param fault_name: str, Name of the fault toggle alarm
        :param fault_source: str, Source of the fault toggle alarm
        :param node_id: str, node id in which fault toggle alarm is present
        :param timeout: int, time to wait get alarm info, default is 60 second

        :return: str, path of fault toggle alarm file or string says "No Alarm found" if alarms are present"""
        self.filter_fault_toggling(alarm_state, fault_id, fault_name, fault_source, node_id, timeout)
        if self.element_exists((By.XPATH, self.locator.ALARM_EMPTY_XPATH.format("fault-toggling"))):
            return "No Alarm found"
        else:
            self.click_enabled_element(self.locator.SAVE_FAULT_TOGGLING_HISTORY, timeout)
            return "Saved Alarm successfully"

    def filter_fault_toggling(self, alarm_state, fault_id, fault_name, fault_source, node_id, timeout):
        """
        Keyword for performing the filter in fault toggle alarm

        :param alarm_state: str, State of the alarm
        :param fault_id: str, id of the  fault toggle alarm
        :param fault_name: str, Name of the fault toggle alarm
        :param fault_source: str, Source of the fault toggle alarm
        :param node_id: str, node id in which fault toggle alarm is present
        :param timeout: int, time to wait get alarm info

        :return: list of dict, every dict info is one line of fault toggle alarm tables
        """
        self.filter_fault_toggling_state(alarm_state, timeout)
        self.clear_fault_toggle_filters(timeout)
        if fault_id is not None:
            self.insert_text_to_enable_element(self.locator.FAULT_ID_FILTER, fault_id, timeout)
        if fault_name is not None:
            self.insert_text_to_enable_element(self.locator.FAULT_NAME_FILTER, fault_name, timeout)
        if fault_source is not None:
            self.insert_text_to_enable_element(self.locator.FAULT_SOURCE_FILTER, fault_source, timeout)
        if node_id is not None:
            self.insert_text_to_enable_element(self.locator.FAULT_NODE_ID_FILTER, node_id, timeout)
        self.click_enabled_element(self.locator.PAGE_FIRST_NAVIGATOR_CSS_PATH, timeout)

    def filter_fault_toggling_state(self, alarm_state, timeout):
        """
        This keyword will select the state of fault toggle alarms
        :param alarm_state: str, State of the alarm
        :param timeout: int, time to wait get alarm info
        """
        self.click_enabled_element(self.locator.FAULT_STATE_FILTER, timeout)
        if self.element_exists(self.locator.ACTIVE_FAULT_ALARM_SELECTED, 2):
            self.click_enabled_element(self.locator.ACTIVE_FAULT_ALARM_CHECK_BOX, timeout)
        if self.element_exists(self.locator.INACTIVE_FAULT_ALARM_SELECTED, 2):
            self.click_enabled_element(self.locator.INACTIVE_FAULT_ALARM_CHECK_BOX, timeout)
        if alarm_state is not None:
            if alarm_state.lower() == "active":
                self.click_enabled_element(self.locator.ACTIVE_FAULT_ALARM_CHECK_BOX, timeout)
            if alarm_state.lower() == "inactive":
                self.click_enabled_element(self.locator.INACTIVE_FAULT_ALARM_CHECK_BOX, timeout)
        self.click_enabled_element(self.locator.FAULT_STATE_FILTER, timeout)

    def _get_fault_toggling_alarm_info(self, timeout):
        """
        This keyword is for read all the details from fault toggle alarms table


        :param timeout: int, time to wait get alarm information

        :return: list of dict, every dict info is one line of alarm tables
        """
        alarm_list = []
        key_list = self.get_fields_info_from_row(self.locator.FAULT_TOGGLING_TABLE_HEADER, timeout)
        number_of_alarm_pages = self.get_text(self.locator.PAGINATION_PAGE_NUMBER, timeout).split(" ")[-1]
        for page in range(1, int(number_of_alarm_pages) + 1):
            number_of_rows = len(self.get_all_matching_elements(self.locator.FAULT_TOGGLING_ROW_XPATH))
            for row in range(1, number_of_rows + 1):
                value_list = self._get_fault_toggling_alarm_row_data(row, key_list)
                alarm_list.append(dict(zip(key_list, value_list)))
            if page == int(number_of_alarm_pages):
                break
            else:
                self.click_enabled_element(self.locator.PAGE_RIGHT_NAVIGATOR_CSS_PATH, timeout)
                time.sleep(5)
        return alarm_list

    def _get_fault_toggling_alarm_row_data(self, row, columns):
        """
        This key word will return all the column  data of given fault toggle alarms  table in a list

        :param row: int, row number
        :param columns: int , number of columns

        :return: list of column data in row
        """
        alarm_row_details = []
        for cell in range(0, len(columns)):
            alarm_row_details.append(
                self._driver.execute_script(self.locator.FAULT_TOGGLING_DATA_JQUERY.format(row, cell)))
        return alarm_row_details

    def clear_fault_toggle_filters(self, timeout):
        """
        This keyword will clear all the applied filters
        """
        fault_toggle_filters = [self.locator.CLEAR_FAULT_ID_FILTER, self.locator.CLEAR_FAULT_NAME_FILTER,
                                self.locator.CLEAR_FAULT_SOURCE_FILTER, self.locator.CLEAR_FAULT_NODE_ID_FILTER]
        for filter in fault_toggle_filters:
            if self.element_exists(filter, 2):
                self.click_enabled_element(filter, timeout)
